arguments.command:
cd /app; python3 - <<'E'
rows=[]
def add(o,d):
    for s,(r,p) in d.items(): rows.append((o,s,r,p,max(r-p,0)))
def k(**kw): return {k.replace('_','-'):v for k,v in kw.items()}
# helper: dict sku->(req,picked)
def mk(req,pick={}):
    return {s:(q,pick.get(s,0)) for s,q in req.items()}
A=lambda n:{f'CP-{i}':n for i in (201,202,203,204,205,211)}
B=lambda n:{f'CP-{i}':n for i in (201,202,203,204,205,206,212)}
add('SO-5501',mk(A(3),{s:1 for s in A(1)}))
add('SO-5502',mk(A(2)))
r=B(2);r.update({'CP-215':2,'CP-216':4,'CP-217':4,'CP-209':2})
add('SO-5503',mk(r,{'CP-216':2}))
r={'CP-201':2,'CP-202':2,'CP-203':2,'CP-204':4,'CP-205':4,'CP-211':2,'CP-215':2,'CP-216':4,'CP-217':4,'CP-209':2,'CP-207':4,'CP-208':2}
add('SO-5504',mk(r,{'CP-215':1,'CP-201':1,'CP-204':2}))
add('SO-5505',mk({'CP-207':4,'CP-208':2,'CP-204':2,'CP-205':4}))
r={'CP-207':2};d=mk(r)
for s in B(0): d[s]=(0,0)
add('SO-5506',d)
add('SO-5507',mk(A(1),{s:1 for s in A(1) if s!='CP-204'}))
add('SO-5508',mk({'CP-207':4,'CP-208':2,'CP-204':2},{'CP-207':5}))
add('SO-5509',mk(B(2),{s:1 for s in B(1)}))
r=B(1);r.update({'CP-215':1,'CP-216':2,'CP-217':2,'CP-209':1})
add('SO-5510',mk(r))
add('SO-5511',mk({'CP-207':4,'CP-208':2,'CP-204':2},{'CP-207':2,'CP-208':1,'CP-204':1}))
add('SO-5512',mk({'CP-207':2,'CP-208':1,'CP-204':1,'CP-210':1}))
with open('kit-reservations.csv','w') as f:
    f.write('order,sku,required,picked,reserved\n')
    for x in sorted(rows): f.write(','.join(map(str,x))+'\n')
E
cat > STATUS.json <<'E'
{"status":"success","summary":"Reconciled reservations for all 12 orders (21 releases/reservations posted in main/reserved) and wrote /app/kit-reservations.csv."}
E
grep -c . kit-reservations.csv
